#[test]
fn post_table() {
    let font = fixture();
    let post = font.post().unwrap();
    assert_eq!(post.version().unwrap(), 0x0002_0000);
    assert!((post.italic_angle().unwrap() - -12.5).abs() < 1e-4);
    assert_eq!(post.underline_position().unwrap(), -50);
    assert_eq!(post.underline_thickness().unwrap(), 10);
    assert_eq!(post.is_fixed_pitch().unwrap(), 1);
    // glyphNameIndex: .notdef -> std[0]; Ccomp -> custom name "Ccomp".
    assert_eq!(post.glyph_name(0).unwrap(), Some(".notdef"));
    assert_eq!(post.glyph_name(1).unwrap(), Some("A"));
    assert_eq!(post.glyph_name(3).unwrap(), Some("Ccomp"));
}

// -- TTC collection ---------------------------------------------------------

#[test]
fn collection_fonts_share_tables() {
    let coll = FontCollection::parse(TTC).unwrap();
    assert_eq!(coll.len(), 2);
    assert_eq!(coll.version(), 0x0001_0000);
    let fonts = coll.fonts().unwrap();
    assert_eq!(fonts.len(), 2);
    // Both fonts see the full table set (shared data).
    for f in &fonts {
        assert_eq!(f.num_glyphs(), 4);
        assert!(f.table(TableTag::Glyf).is_some());
        let cmap = f.cmap().unwrap();
        assert_eq!(cmap.codepoint('A').map(GlyphId::to_u32), Some(1));
    }
    // Distinct name records.
    assert_eq!(
        fonts[0].name().unwrap().family().as_deref(),
        Some("FontParse Test")
    );
    assert_eq!(
        fonts[1].name().unwrap().family().as_deref(),
        Some("FontParse Alt")
    );

    // Extraction produces a standalone font with identical content.
    let extracted = OwnedFont::from_collection(TTC, 1).unwrap();
    let ex = extracted.as_font_ref().unwrap();
    assert_eq!(ex.num_glyphs(), 4);
    assert_eq!(
        ex.name().unwrap().family().as_deref(),
        Some("FontParse Alt")
    );
    // Table bytes are byte-identical to the shared originals.
    assert_eq!(ex.table(TableTag::Glyf), fonts[1].table(TableTag::Glyf));
    assert_eq!(ex.table(TableTag::Cmap), fonts[1].table(TableTag::Cmap));

    // Out-of-range index.
    assert_eq!(
        coll.font(2).unwrap_err(),
        ParseError::CollectionIndexOutOfBounds { index: 2, count: 2 }
    );
    assert_eq!(
        OwnedFont::from_collection(TTC, 7).unwrap_err(),
        ParseError::CollectionIndexOutOfBounds { index: 7, count: 2 }
    );
    // Not a TTC.
    assert_eq!(
        FontCollection::parse(TTF).unwrap_err(),
        ParseError::InvalidSfnt
    );
}

// -- WOFF / WOFF2 ------------------------------------------------------------

#[cfg(feature = "woff")]
#[test]
fn woff_round_trip() {
    let font = OwnedFont::from_woff(WOFF).unwrap();
    let f = font.as_font_ref().unwrap();
    assert_eq!(f.num_glyphs(), 4);
    assert_eq!(f.head().unwrap().units_per_em().unwrap(), 1000);
    let cmap = f.cmap().unwrap();
    assert_eq!(cmap.codepoint('A').map(GlyphId::to_u32), Some(1));
    // Every table of the original SFNT is byte-identical, except head's
    // checkSumAdjustment (recomputed for the new layout).
    let orig = fixture();
    for (tag, _sum, _off, _len) in orig.table_directory() {
        let (Some(a), Some(b)) = (
            orig.table_by_tag(font_parse::Tag::new(&tag)),
            f.table_by_tag(font_parse::Tag::new(&tag)),
        ) else {
            panic!("table missing after woff decode: {tag:?}");
        };
        if &tag == b"head" {
            assert_eq!(&a[..8], &b[..8]);
            assert_eq!(&a[12..], &b[12..]);
        } else {
            assert_eq!(a, b, "table {:?}", core::str::from_utf8(&tag));
        }
    }
    assert_eq!(f.head().unwrap().magic_number().unwrap(), 0x5F0F_3CF5);
}

#[cfg(feature = "woff2")]
#[test]
fn woff2_round_trip() {
    let font = OwnedFont::from_woff2(WOFF2).unwrap();
    let f = font.as_font_ref().unwrap();
    assert_eq!(f.num_glyphs(), 4);
    assert_eq!(f.head().unwrap().units_per_em().unwrap(), 1000);
    // Transform marker set (head.flags bit 11).
    assert_ne!(f.head().unwrap().flags().unwrap() & 0x0800, 0);
    let cmap = f.cmap().unwrap();
    assert_eq!(cmap.codepoint('A').map(GlyphId::to_u32), Some(1));
    assert_eq!(cmap.codepoint('B').map(GlyphId::to_u32), Some(2));
    // Outlines match the TTF's.
    let a_ttf = fixture().outline(GlyphId::new(1)).unwrap().unwrap();
    let a_w2 = f.outline(GlyphId::new(1)).unwrap().unwrap();
    assert_eq!(a_ttf, a_w2);
    let c_ttf = fixture().outline(GlyphId::new(3)).unwrap().unwrap();
    let c_w2 = f.outline(GlyphId::new(3)).unwrap().unwrap();
    assert_eq!(c_ttf, c_w2);
    // hmtx reconstructed from bboxes where the transform dropped lsbs.
    assert_eq!(f.advance_width(GlyphId::new(1)).unwrap(), 600);
    assert_eq!(f.hmtx().unwrap().left_side_bearing(1).unwrap(), 40);
    // Non-transformed tables are byte-identical, except head (checkSumAdjustment
    // recomputed + transform marker flag).
    let orig = fixture();
    for tag in [TableTag::Hhea, TableTag::Maxp, TableTag::Cmap] {
        assert_eq!(orig.table(tag), f.table(tag), "{tag:?}");
    }
    {
        let (a, b) = (
            orig.table(TableTag::Head).unwrap(),
            f.table(TableTag::Head).unwrap(),
        );
        assert_eq!(&a[..8], &b[..8]); // version + fontRevision
        assert_eq!(&a[12..16], &b[12..16]); // magicNumber
        assert_eq!(&a[18..], &b[18..]); // rest after flags
    }
}

#[cfg(feature = "woff2")]
#[test]
fn woff2_rejects_bad_containers() {
    let mut bad = WOFF2.to_vec();
    bad[0] = b'X';
    assert!(OwnedFont::from_woff2(&bad).is_err());
    assert!(OwnedFont::from_woff2(&WOFF2[..40]).is_err());
}

// -- variable font -------------------------------------------------------------

#[test]
fn variable_font_axes_and_instances() {
    let font = FontRef::new(VF).unwrap();
    assert!(font.is_variable());
    let vf = font.variable().unwrap();
    let axes = vf.axes().unwrap();
    assert_eq!(axes.len(), 1);
    let axis = &axes[0];
    assert_eq!(axis.tag.to_be_bytes(), *b"wght");
    assert_eq!(axis.min.to_f32(), 400.0);
    assert_eq!(axis.default.to_f32(), 400.0);
    assert_eq!(axis.max.to_f32(), 900.0);
    let instances = vf.instances().unwrap();
    assert_eq!(instances.len(), 1);
    assert_eq!(instances[0].name_id, 257);
    assert_eq!(instances[0].coordinates[0].to_f32(), 600.0);
}

#[test]
fn avar_segment_map() {
    let font = FontRef::new(VF).unwrap();
    let vf = font.variable().unwrap();
    let avar = vf.avar().expect("fixture has avar");
    assert_eq!(avar.axis_count(), 1);
    let maps = avar.segment_maps().unwrap();
    assert_eq!(maps.len(), 1);
    let m = &maps[0];
    // Map: (-1,-1), (0,0), (0.5,0.6), (1,1).
    let f2 = |v: f32| font_parse::F2Dot14::from_f32(v);
    assert_eq!(m.map(f2(-1.0)).to_f32(), -1.0);
    assert_eq!(m.map(f2(0.0)).to_f32(), 0.0);
    assert_eq!(m.map(f2(1.0)).to_f32(), 1.0);
    let mapped = m.map(f2(0.5)).to_f32();
    assert!((mapped - 0.6).abs() < 0.001, "{mapped}");
    // Interpolation inside the 0.0..0.5 segment.
    let mid = m.map(f2(0.25)).to_f32();
    assert!((mid - 0.3).abs() < 0.001, "{mid}");
}

#[test]
fn gvar_deltas() {
    let font = FontRef::new(VF).unwrap();
    // gid 1 (A): 4 outline points + 4 phantom = 8 delta slots.
    let tuples = font.gvar_deltas(GlyphId::new(1)).unwrap();
    assert_eq!(tuples.len(), 1);
    let t = &tuples[0];
    assert!(t.has_private_points() || t.point_numbers.is_none());
    assert_eq!(t.x_deltas.len(), 8);
    assert_eq!(t.y_deltas.len(), 8);
    assert_eq!(t.y_deltas, &[0; 8]);
    // Points 0,1 and 4,5 move +50 in x (master A shifted 100 -> 150).
    assert_eq!(&t.x_deltas[..], &[50, 50, 0, 0, 50, 50, 0, 0]);
    // Shared peak tuple: (min=0, peak=1, max=1) on wght.
    assert_eq!(t.peak.len(), 1);
    assert!((t.peak[0].to_f32() - 1.0).abs() < 1e-6);

    // gid 3 (Ccomp): 1 component + 4 phantom = 5 delta slots.
    let tuples = font.gvar_deltas(GlyphId::new(3)).unwrap();
    assert_eq!(tuples.len(), 1);
    let t = &tuples[0];
    assert_eq!(t.x_deltas.len(), 5);
    assert_eq!(&t.x_deltas[..], &[0, 25, 25, 0, 0]);

    // gid 0/2 have no deltas.
    assert!(font.gvar_deltas(GlyphId::new(0)).unwrap().is_empty());
    assert!(font.gvar_deltas(GlyphId::new(2)).unwrap().is_empty());

    // Out-of-range ids are empty, not errors.
    assert!(font.gvar_deltas(GlyphId::new(99)).unwrap().is_empty());

    // Non-variable fonts have no deltas.
    assert!(fixture().gvar_deltas(GlyphId::new(1)).unwrap().is_empty());
}

#[test]
fn variable_normalization() {
    let font = FontRef::new(VF).unwrap();
    let vf = font.variable().unwrap();
    let fxd = |v: f32| font_parse::Fixed::from_f64(f64::from(v));
    // Default maps to 0; extremes to ±1 (avar is identity at the anchors).
    assert_eq!(vf.normalize(0, fxd(400.0)).unwrap().to_f32(), 0.0);
    assert_eq!(vf.normalize(0, fxd(900.0)).unwrap().to_f32(), 1.0);
    assert_eq!(vf.normalize(0, fxd(400.0 - 400.0)).unwrap().to_f32(), -1.0);
    // 650 sits above default: (650-400)/500 = 0.5 -> avar maps 0.5 -> 0.6.
    let mid = vf.normalize(0, fxd(650.0)).unwrap().to_f32();
    assert!((mid - 0.6).abs() < 0.001, "{mid}");
    // Bad axis index.
    assert!(vf.normalize(9, fxd(400.0)).is_err());
}

