#[test]
fn checksum_util_public_wrapper() {
    // Public re-export of the internal checksum for directory verification.
    assert_eq!(font_parse::table_checksum_public(&[0, 0, 0, 1]), 1);
    assert_eq!(
        font_parse::table_checksum_public(&[0xFF, 0xFF, 0xFF, 0xFF]),
        u32::MAX
    );
    // Non-aligned tail is zero-padded.
    assert_eq!(font_parse::table_checksum_public(&[1]), 0x0100_0000);
}
